#
# THE VENDORED QDRANT EDGE IS THE PUBLISHED CRATE PLUS THE ONE RECORDED CHANGE, AND NOTHING ELSE.
#
# richos/app/third-party/qdrant-edge is qdrant-edge 0.8.0 from crates.io, carried in the tree
# because the published crate does not compile on this app's Rust (RICHOS-PATCH.md beside it).
# What this suite claims about every file it covers is exactly that: its bytes are the bytes
# Qdrant published (SHA-256 per file, pinned in qdrant-edge-vendored.published.json, taken from
# qdrant-edge-0.8.0.crate), except src/shard/optimize.rs, which is the published file with the
# one change RICHOS-PATCH.md describes and no other; LICENSE and RICHOS-PATCH.md are the two
# added files. The crate's own behavior is upstream's, tested upstream; what it does inside
# RichOS is exercised by crates/richos-search's tests (vector.rs, tests/service.rs).
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PYTHONDONTWRITEBYTECODE=1 python3 - "$here/../third-party/qdrant-edge" "$here/qdrant-edge-vendored.published.json" <<'PY'
import hashlib, json, os, sys
root, pins_path = sys.argv[1], sys.argv[2]
pins = json.load(open(pins_path))
published = pins["published_sha256"]
found = sorted(os.path.relpath(os.path.join(d, f), root) for d, _, fs in os.walk(root) for f in fs)
expected = sorted(set(published) | set(pins["added_by_richos"]))
if found != expected:
    sys.exit(f"  FAIL  vendored files differ from the published crate: missing {sorted(set(expected)-set(found))}, extra {sorted(set(found)-set(expected))}")
print(f"  PASS  {len(published)} published files present, {len(pins['added_by_richos'])} added, nothing else")
def sha(rel):
    return hashlib.sha256(open(os.path.join(root, rel), "rb").read()).hexdigest()
changed = [rel for rel in published if sha(rel) != published[rel]]
if changed != pins["changed_by_richos"]:
    sys.exit(f"  FAIL  files that differ from the published bytes: {changed}; recorded: {pins['changed_by_richos']}")
print("  PASS  every other file is byte-identical to qdrant-edge 0.8.0 as published")
text = open(os.path.join(root, "src/shard/optimize.rs")).read()
patched_use = '            debug_assert!(\n                matches!(proxy.wrapped_segment(), LockedSegment::Original(_)),\n'
published_use = '            debug_assert_matches!(\n                proxy.wrapped_segment(),\n                LockedSegment::Original(_),\n'
if text.count(patched_use) != 1 or "debug_assert_matches" in text:
    sys.exit("  FAIL  optimize.rs does not carry exactly the recorded change")
restored = text.replace(patched_use, published_use).replace("use std::collections::HashSet;\n", "use std::collections::HashSet;\nuse std::debug_assert_matches;\n", 1)
if hashlib.sha256(restored.encode()).hexdigest() != published["src/shard/optimize.rs"]:
    sys.exit("  FAIL  optimize.rs differs from the published file by more than the recorded change")
print("  PASS  optimize.rs is the published file with only the recorded two-line change")
note = open(os.path.join(root, "RICHOS-PATCH.md")).read()
if "debug_assert_matches" not in note or "src/shard/optimize.rs" not in note:
    sys.exit("  FAIL  RICHOS-PATCH.md no longer names the change")
if "Apache License" not in open(os.path.join(root, "LICENSE")).read():
    sys.exit("  FAIL  the Apache-2.0 LICENSE is missing")
print("  PASS  the change is written down beside it and the Apache-2.0 license travels with it")
PY
